function hideIuWlOuts(el, acc) {
  if (el == null || el.isJsonNull()) return
  if (el.isJsonPrimitive()) { var s = String(el.getAsString()); if (s.indexOf(':') > 0) acc.push(s) }
  else if (el.isJsonArray()) { for (var i = 0; i < el.size(); i++) hideIuWlOuts(el.get(i), acc) }
  else if (el.isJsonObject()) { var it = el.keySet().iterator(); while (it.hasNext()) { var k = it.next(); if (k != 'count' && k != 'amount') hideIuWlOuts(el.get(k), acc) } }
}

ServerEvents.recipes(function (event) {
  var set = {}
  HIDE_IU_WL.forEach(function (id) { set[id] = true })
  var ids = []
  event.forEachRecipe({}, function (r) {
    try {
      var json = r.json, outs = []
      ;['result', 'results', 'output', 'outputs'].forEach(function (k) { if (json.has(k)) hideIuWlOuts(json.get(k), outs) })
      if (outs.length && outs.every(function (o) { return set[o] })) ids.push(String(r.getId()))
    } catch (e) {}
  })
  ids.forEach(function (id) { event.remove({ id: id }) })
  console.info('[hide_iu_whitelist] items: ' + HIDE_IU_WL.length + ', recipes removed: ' + ids.length)
})
